import axios from 'axios';
import { getLoggedInUser } from '../utils/config.util';
import { MKDB_BASE_URL } from '../utils/env.util';
import logger from '../utils/logger.util';
import login from './login';

const deleteDb = async (dbId: string) => {
  let userInfo = await getLoggedInUser();
  if (!userInfo) {
    await login();
    userInfo = await getLoggedInUser();
    if (!userInfo)
      return logger.log('You must be logged in to create a database');
  }

  const res = await axios
    .delete(`${MKDB_BASE_URL}/api/databases/${dbId}`, {
      headers: {
        Authorization: userInfo.apiToken,
        'Content-Type': 'application/json',
      },
    })
    .catch((error) => {
      logger.dev.log('error:', [
        error.response.status,
        error.response.statusText,
      ]);

      logger.log('an error occurred trying to delete that database');

      return undefined;
    });

  logger.dev.log('res', res?.data);

  if (res?.status === 200) {
    logger.log(`database deleted successfully`);
  }

  return null;
};

export default deleteDb;
